import xml.etree.ElementTree as ET, csv, sys

tree = ET.parse('/tmp/vasco_candidates.vot')
root = tree.getroot()
ns = {'vot': 'http://www.ivoa.net/xml/VOTable/v1.3'}

rows = []
for resource in root.findall('.//vot:RESOURCE', ns):
    for table in resource.findall('vot:TABLE', ns):
        data = table.find('vot:DATA', ns)
        if data is not None:
            td = data.find('vot:TABLEDATA', ns)
            if td is not None:
                for tr in td.findall('vot:TR', ns):
                    vals = []
                    for cell in tr.findall('vot:TD', ns):
                        vals.append(cell.text or '')
                    rows.append(vals)

print(f'Total rows: {len(rows)}')
print(f'Cols per row: {len(rows[0])}')
print('First 3 rows:')
for r in rows[:3]:
    print(r)
print()
print('Last 3 rows:')
for r in rows[-3:]:
    print(r)
" 2>&1

