# ---------------------------------------------------------------------------
# Statistics
# ---------------------------------------------------------------------------

def nearest_neighbor_stats(ra, dec):
    """Compute mean, median, min nearest-neighbor angular distances (deg)."""
    n = len(ra)
    if n < 2:
        return {"mean": None, "median": None, "min": None, "n": n}
    dists = []
    for i in range(n):
        d = angular_sep(ra[i], dec[i], ra, dec)
        d = d[d > 0]
        if len(d) > 0:
            dists.append(np.min(d))
    dists = np.array(dists)
    return {
        "mean": float(np.mean(dists)),
        "median": float(np.median(dists)),
        "min": float(np.min(dists)),
        "n": n,
    }


def close_pairs(ra, dec, threshold_deg=1.0):
    """Count pairs with angular separation < threshold_deg."""
    n = len(ra)
    if n < 2:
        return 0
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if angular_sep(ra[i], dec[i], ra[j], dec[j]) < threshold_deg:
                count += 1
    return count

# Determine verdict
all_zs = []
for label in null_labels:
    for metric, zval in z_scores[label[0]].items():
        all_zs.append(abs(zval))

max_abs_z = max(all_zs) if all_zs else 0

if max_abs_z >= 5.0:
    verdict_parts.append("STRUCTURE_SIGNAL")
elif max_abs_z >= 3.0:
    verdict_parts.append("UNDERDETERMINED")
else:
    verdict_parts.append("NO_SIGNAL")

# Check null separation: signal must beat ALL nulls
